"""Origin framing and evidence audit extension.

Parses consecutive HTTP/1.1 requests out of every recorded capture channel,
attributes raw request bytes back to their producing case and derives the
paired-evidence diagnostics described by the contract.
"""
import bisect
import re

from modules.byte_program import (MAX, Cat, Lit, concat_all, hash_bytes,
                                  hash_range, materialize, byte_at, window,
                                  MATERIALIZE_LIMIT)

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")

CR = 13
LF = 10
SP = 32
HTAB = 9
LINE_LIMIT = 8192
BLOCK_LIMIT = 65536
FIELD_LIMIT = 128
REQUEST_LIMIT = 20000
CHUNK_LIMIT = 40000

OK = 0
SYNTAX = 1
INCOMPLETE = 2

HEXDIGITS = frozenset(b'0123456789abcdefABCDEF')
FORBIDDEN_TRAILER = (b'host', b'content-length', b'transfer-encoding')
LENGTH = b'content-length'
ENCODING = b'transfer-encoding'
VERSION = b'HTTP/1.1'


class Reader:
    """Logical byte stream: structural hashing plus bounded direct access."""

    __slots__ = ('node', 'length', 'data')

    def __init__(self, node):
        self.node = node
        self.length = node.length
        self.data = None
        if node.length and node.length <= MATERIALIZE_LIMIT:
            if isinstance(node, Lit):
                self.data = node.data
            else:
                self.data = materialize(node)

    def at(self, index):
        data = self.data
        return data[index] if data is not None else byte_at(self.node, index)

    def block(self, start, end):
        data = self.data
        return data[start:end] if data is not None else window(self.node, start, end)

    def find_lf(self, start, stop):
        data = self.data
        return data.find(b'\n', start, stop) if data is not None else \
            _scan_lf(self.node, start, stop)

    def region(self, start, end):
        return hash_range(self.node, start, end)


def _scan_lf(node, start, stop):
    if isinstance(node, Lit):
        return node.data.find(b'\n', start, stop)
    if start >= stop:
        return -1
    if isinstance(node, Cat):
        previous = 0
        for position, bound in enumerate(node.offsets):
            if bound <= start:
                previous = bound
                continue
            if stop <= previous:
                break
            left = max(start, previous)
            right = min(stop, bound)
            found = _scan_lf(node.parts[position], left - previous, right - previous)
            if found >= 0:
                return previous + found
            previous = bound
        return -1
    block = window(node, start, stop)
    found = block.find(b'\n')
    return -1 if found < 0 else start + found


def encode_fields(fields):
    out = bytearray(len(fields).to_bytes(8, 'big'))
    for name, value in fields:
        out += len(name).to_bytes(8, 'big')
        out += name
        out += len(value).to_bytes(8, 'big')
        out += value
    return bytes(out)


def fingerprint_bytes(data):
    return {'n': len(data), 'h': '%016x' % hash_bytes(data)}


def _visible(data):
    for value in data:
        if not 33 <= value <= 126:
            return False
    return True


def _field_value_ok(data):
    for value in data:
        if value == HTAB:
            continue
        if not 32 <= value <= 126:
            return False
    return True


def _split_field(data):
    index = data.find(b':')
    if index <= 0:
        return None
    name = data[:index]
    if TOKEN.match(name) is None:
        return None
    value = data[index + 1:]
    if not _field_value_ok(value):
        return None
    return name, value.strip(b' \t')


def _content_length(values):
    total = None
    for value in values:
        for member in value.split(b','):
            digits = member.strip(b' \t')
            if not digits:
                return None
            for symbol in digits:
                if not 48 <= symbol <= 57:
                    return None
            trimmed = digits.lstrip(b'0')
            if len(trimmed) > 19:
                return None
            number = int(trimmed or b'0')
            if number > MAX:
                return None
            if total is None:
                total = number
            elif total != number:
                return None
    return total


class Runs:
    """Owner labels for the concatenated capture, by logical offset."""

    def __init__(self, parts):
        self.labels = []
        self.starts = []
        position = 0
        for part in parts:
            length = part['data'].length
            label = part['case']
            if length:
                if self.labels and self.labels[-1] == label:
                    pass
                else:
                    self.labels.append(label)
                    self.starts.append(position)
                position += length
        self.ends = self.starts[1:] + [position]
        self.total = position

    def owners_of(self, start, end):
        labels = []
        counts = {}
        order = []
        position = start
        while position < end:
            index = bisect.bisect_right(self.starts, position) - 1
            bound = self.ends[index]
            stop = min(bound, end)
            if stop > position:
                label = self.labels[index]
                amount = stop - position
                if label not in counts:
                    counts[label] = 0
                    order.append(label)
                counts[label] += amount
            position = stop
        return [[label, counts[label]] for label in order]

    def label_at(self, offset):
        index = bisect.bisect_right(self.starts, offset) - 1
        return self.labels[index]


class ChannelParser:
    def __init__(self, reader, runs, audit):
        self.reader = reader
        self.runs = runs
        self.audit = audit
        self.length = reader.length

    # -- low level ---------------------------------------------------------- #
    def line(self, position):
        reader = self.reader
        remaining = self.length - position
        if remaining <= 0:
            return INCOMPLETE, 0, position
        stop = position + (8194 if remaining >= 8194 else remaining)
        found = reader.find_lf(position, stop)
        if found < 0:
            return (OK if False else (INCOMPLETE if remaining <= 8193 else SYNTAX)), 0, position
        if found == position or reader.at(found - 1) != CR or found - position - 1 > LINE_LIMIT:
            return SYNTAX, 0, position
        return OK, found - position - 1, found + 1

    # -- blocks ------------------------------------------------------------- #
    def header_block(self, position, size, count, trailer=False):
        """Read a field block; ``size``/``count`` are already consumed."""
        reader = self.reader
        fields = []
        while True:
            state, length, nxt = self.line(position)
            if state != OK:
                return state, None, position, fields
            size += length + 2
            if size > BLOCK_LIMIT:
                return SYNTAX, None, position, fields
            if length == 0:
                return OK, nxt, position, fields
            field = _split_field(reader.block(position, position + length))
            if field is None:
                return SYNTAX, None, position, fields
            if trailer and field[0].lower() in FORBIDDEN_TRAILER:
                return SYNTAX, None, position, fields
            fields.append(field)
            count += 1
            if count > FIELD_LIMIT:
                return SYNTAX, None, position, fields
            position = nxt

    # -- chunked ------------------------------------------------------------ #
    def chunked_body(self, position):
        reader = self.reader
        total = 0
        digest = 0
        while True:
            state, length, nxt = self.line(position)
            if state != OK:
                return state, None, position, total, digest
            self.audit.chunk_lines += 1
            if self.audit.chunk_lines > CHUNK_LIMIT:
                raise ValueError('chunk budget')
            line = reader.block(position, position + length)
            position = nxt
            split = line.find(b';')
            if split < 0:
                digits, suffix = line, None
            else:
                digits, suffix = line[:split], line[split + 1:]
            if not digits:
                return SYNTAX, None, position, total, digest
            for symbol in digits:
                if symbol not in HEXDIGITS:
                    return SYNTAX, None, position, total, digest
            if suffix is not None and not _field_value_ok(suffix):
                return SYNTAX, None, position, total, digest
            trimmed = digits.lstrip(b'0')
            if len(trimmed) > 16:
                return SYNTAX, None, position, total, digest
            amount = int(trimmed or b'0', 16)
            if amount > MAX:
                return SYNTAX, None, position, total, digest
            if amount == 0:
                state, end, _, trailers = self.header_block(position, 0, 0, True)
                if state != OK:
                    return state, None, position, total, digest
                return OK, end, trailers, total, digest
            if self.length - position < amount:
                return INCOMPLETE, None, position, total, digest
            after = position + amount
            if self.length - after < 2:
                return INCOMPLETE, None, position, total, digest
            if reader.at(after) != CR or reader.at(after + 1) != LF:
                return SYNTAX, None, position, total, digest
            count, value = reader.region(position, after)
            digest = (digest * pow(257, count, 1 << 64) + value) & ((1 << 64) - 1)
            total += count
            if total > MAX:
                raise ValueError('body length')
            position = after + 2

    # -- requests ----------------------------------------------------------- #
    def request(self, position):
        start = position
        state, length, nxt = self.line(position)
        if state != OK:
            return state, None
        reader = self.reader
        line = reader.block(position, position + length)
        parts = line.split(b' ')
        if len(parts) != 3:
            return SYNTAX, None
        method, target, version = parts
        if not method or TOKEN.match(method) is None:
            return SYNTAX, None
        if not target or not _visible(target) or version != VERSION:
            return SYNTAX, None
        size = length + 2
        state, end, _, fields = self.header_block(nxt, size, 1)
        if state != OK:
            return state, None
        position = end
        lengths = [value for name, value in fields if name.lower() == LENGTH]
        encodings = [value for name, value in fields if name.lower() == ENCODING]
        framing = 'none'
        body_length = 0
        body_digest = 0
        trailers = []
        if encodings:
            if len(encodings) > 1 or lengths or \
                    encodings[0].lower() != b'chunked':
                return SYNTAX, None
            framing = 'chunked'
            state, position, trailers, body_length, body_digest = self.chunked_body(position)
            if state != OK:
                return state, None
        elif lengths:
            declared = _content_length(lengths)
            if declared is None:
                return SYNTAX, None
            framing = 'length'
            if self.length - position < declared:
                return INCOMPLETE, None
            body_length, body_digest = reader.region(position, position + declared)
            position += declared
        hosts = [value for name, value in fields if name.lower() == b'host']
        record = {
            'start': start,
            'end': position,
            'method': fingerprint_bytes(method),
            'target': fingerprint_bytes(target),
            'host': fingerprint_bytes(hosts[0].lower()) if len(hosts) == 1
                    else fingerprint_bytes(b''),
            'host_count': len(hosts),
            'headers': fingerprint_bytes(encode_fields(fields)),
            'body': {'n': body_length, 'h': '%016x' % body_digest},
            'trailers': fingerprint_bytes(encode_fields(trailers)),
            'framing': framing,
            '_fields': fields,
            '_identity': (method, target, hosts),
        }
        return OK, record


class Audit:
    def __init__(self):
        self.chunk_lines = 0
        self.requests = 0


def audit_channels(channels, cases, sent):
    """Return channel records and fill per-case origin counts and flags."""
    expects = {case['name']: case['expect'] for case in cases}
    audit = Audit()
    records = []
    origin_owners = {}
    per_case_requests = {}
    for index, channel in enumerate(channels):
        node = concat_all([part['data'] for part in channel['parts']])
        reader = Reader(node)
        runs = Runs(channel['parts'])
        parser = ChannelParser(reader, runs, audit)
        position = 0
        parsed = []
        error = None
        while position < reader.length:
            state, record = parser.request(position)
            if state == SYNTAX:
                error = {'kind': 'syntax', 'offset': position}
                break
            if state == INCOMPLETE:
                error = {'kind': 'incomplete', 'offset': position}
                break
            audit.requests += 1
            if audit.requests > REQUEST_LIMIT:
                raise ValueError('request budget')
            parsed.append(record)
            position = record['end']
        committed = []
        cursor = 0
        consumed = 0
        for part in channel['parts']:
            consumed += part['data'].length
            while cursor < len(parsed) and parsed[cursor]['end'] <= consumed:
                cursor += 1
            committed.append(cursor)
        rows = []
        for record in parsed:
            start = record['start']
            end = record['end']
            owner = runs.label_at(start) if end > start else None
            owners = runs.owners_of(start, end)
            flags = set()
            if owner is None:
                flags.add('unattributed')
            if len(owners) > 1:
                flags.add('mixed_owner')
            hosts = record['_identity'][2]
            if not hosts:
                flags.add('missing_host')
            elif len(hosts) > 1:
                flags.add('multiple_host')
            if owner is not None:
                method, target, _ = record['_identity']
                expect = expects[owner]
                if method != expect['method'].encode('ascii') or \
                        target != expect['target'].encode('ascii') or \
                        len(hosts) != 1 or \
                        hosts[0].lower() != expect['host'].encode('ascii').lower():
                    flags.add('identity')
            record['owner'] = owner
            record['owners'] = owners
            record['_flags'] = flags
            record['_channel'] = index
            rows.append(record)
        records.append((channel['name'], reader, rows))
    # owner ordering: channel array order, then byte order inside a channel
    seen = {}
    origin_count = {}
    case_flags = {}
    ordered = []
    for name, reader, rows in records:
        ordered.extend(rows)
    for record in ordered:
        owner = record['owner']
        if owner is not None:
            count = seen.get(owner, 0)
            seen[owner] = count + 1
            if count:
                record['_flags'].add('extra')
            origin_count[owner] = origin_count.get(owner, 0) + 1
            bucket = case_flags.setdefault(owner, set())
            for flag in record['_flags']:
                if flag == 'identity':
                    bucket.add('identity')
                elif flag == 'mixed_owner':
                    bucket.add('mixed_origin')
    by_name = {row['name']: row for row in sent}
    for name, row in by_name.items():
        count = origin_count.get(name, 0)
        row['origin_count'] = count
        flags = set(case_flags.get(name, ()))
        if row['request_frames'] > 0 and count == 0:
            flags.add('missing_origin')
        if count > 1:
            flags.add('extra_origin')
        if count > 0 and row['request_frames'] == 0:
            flags.add('unsent_origin')
        row['flags'] = sorted(flags)
    unsent = {name for name, row in by_name.items() if row['request_frames'] == 0}
    for name in unsent:
        pass
    output = []
    for name, reader, rows in records:
        published = []
        for record in rows:
            owner = record['owner']
            flags = record['_flags']
            if owner is not None and owner in unsent:
                flags.add('unsent')
            published.append({
                'start': record['start'],
                'end': record['end'],
                'method': record['method'],
                'target': record['target'],
                'host': record['host'],
                'host_count': record['host_count'],
                'headers': record['headers'],
                'body': record['body'],
                'trailers': record['trailers'],
                'framing': record['framing'],
                'owner': owner,
                'owners': record['owners'],
                'flags': sorted(flags),
            })
        output.append({
            'name': name,
            'bytes': {'n': reader.length, 'h': '%016x' % reader.node.hash},
            'requests': published,
            'committed': committed_for(rows, reader),
            'error': None,
        })
    return output
